"""DeepSeek-V4 sparse MLA decode, C128 layers (FlyDSL, gfx950): `run`, the AKLR entry point.

Per request b the keys are swa_len[b] rows of the sliding-window pool (sparse_indices) then extra_len[b] rows of the
compressed pool (extra_sparse_indices); a negative index is a hole. A row is 448 fp8 codes (7 groups of 64 dims, each
with a UE8M0 scale byte c) and 64 bf16 rope dims; a code's value is the reference's bit assembly: the bf16 with the code's sign,
exponent field e + c - 7 and mantissa, i.e. (1 + m/8) 2^(e-7) 2^(c-127) (no subnormal codes). With K = kv_scale x rows,
    out[b, h] = sum_k p_k K_k / (sum_k p_k + e^(sink_h - m)),  p_k = e^(sm_scale q_h.K_k - m),  lse = log sum_k p_k + m.

Two launches on the caller's stream (no workgroup ever waits for another; any residency works):
1. split kernel, grid (GMAX, H/64), 256 threads = 4 waves, one workgroup a CU (159 KB LDS).
   Work split (uniform, computed by every workgroup from the lengths): request b has nt_b = ceil((swa_len +
   extra_len) / 64) tiles of 64 keys; tpw tiles a workgroup (class Work), and request b's tiles go to the
   W_b = ceil(nt_b / tpw) workgroups J_b .. J_b + W_b - 1 (prefix sums), tpw consecutive tiles each.
   A workgroup's four waves take every role in turn, tile by tile:
   - gather: thread (row tid/4, quarter tid%4) loads its quarter of a row (144 B) and the 8 scale bytes into
     registers, two tiles ahead; the workgroup's indices are staged in LDS first;
   - dequantize: the row into one of two f16 K tiles in LDS (bias row: 0 or -inf for a missing key);
   - QK: wave w owns heads 16w .. 16w+15: S = K Q^T, 16x16x32 f16 MFMAs, Q (f16) in registers;
   - softmax: online, against a lazily-updated reference max (moved only when a tile's max exceeds it by 2^8), P f16;
   - PV: wave w owns dims 128w .. 128w+127 of all 64 heads: O += K^T P (P through LDS, K^T by transposing LDS reads).
   It stores its slot's (m, l) per head and O / l as f16, the last tile's O block by block as its MFMAs finish;
   workgroup (0, 0) also stores every request's (J_b, W_b).
2. combine kernel, block (request, head group, slice of a 1 KB part of O): the request's slots are J_b .. J_b + W_b - 1
   (from the split kernel's table); each thread merges a strided share of them for 8 values (2 heads x 4 dims) in registers, group 0 merges the shares through LDS, adds the
   sink and writes out (bf16) and lse.

Exactness (the formats it narrows to; accumulation is f32 throughout). Q, the rope dims, P and each partial's O / l
are f16, so the kernel is exact enough (within the error bound of the deployed arithmetic) for:
  - |q| and |rope| < 65504;
  - group scale bytes c <= 134 (group magnitudes |K| < 2^16 before kv_scale): K is exact in f16 for c in [120, 134];
    for c in [103, 120) its smallest codes round to f16 subnormals (absolute error <= 2^-25) and groups with c < 103
    (|K| < 2^-15) flush to zero, both within 2^-12 of the row's largest |K| as long as that is >= 2^-3 - which covers
    group magnitudes from 2^-10 to 2^10 within a row.
"""
import functools
import math
import types

import torch
import flydsl.compiler as flyc
import flydsl.expr as fx
from flydsl._mlir import ir
from flydsl._mlir.dialects import arith, llvm, rocdl, scf, vector

D = 512
TILE = 64
PITCH = 1056                      # LDS bytes a dequantized K row (512 f16 + 32 pad)
BUF = TILE * PITCH + 256          # a K tile and its bias row
MAXT = 72                         # most tiles a workgroup takes (its indices are staged in LDS)
IDXB = 4 * MAXT * TILE
LDS_SPLIT = 2 * BUF + IDXB + 8192 + 512
KB = 8                            # QK: K reads in flight a wave
DTB = 2                           # PV: dim blocks of K^T reads in flight
LOG2E = 1.4426950408889634
NEG_BIG = -1.0e30

# combine configuration a (batch, heads): (threads a block, slot groups, slots a group a round)
_COMBINE = types.MappingProxyType({
    (1, 64): (256, 16, 4), (2, 64): (256, 8, 4), (4, 64): (512, 8, 4), (8, 64): (512, 8, 8),
    (1, 128): (512, 16, 4), (2, 128): (512, 8, 8), (4, 128): (512, 8, 8),
})


# ---------------------------------------------------------------- IR helpers
def i32t():
    return ir.IntegerType.get_signless(32)


def i64t():
    return ir.IntegerType.get_signless(64)


def f32t():
    return ir.F32Type.get()


def bf16t():
    return ir.BF16Type.get()


def f16t():
    return ir.F16Type.get()


def vt(n, t):
    return ir.VectorType.get([n], t)


def ci(v, t=None):
    t = t or i32t()
    if t == i32t() and v >= 2 ** 31:
        v -= 2 ** 32
    return arith.constant(t, ir.IntegerAttr.get(t, int(v)))


def cf(v):
    return arith.constant(f32t(), ir.FloatAttr.get(f32t(), float(v)))


def vsplat(n, t, v):
    ty = vt(n, t)
    attr = ir.FloatAttr.get(t, float(v)) if t in (f32t(), bf16t(), f16t()) else ir.IntegerAttr.get(t, int(v))
    return arith.constant(ty, ir.DenseElementsAttr.get_splat(ty, attr))


def add(a, b):
    return arith.addi(a, b)


def sub(a, b):
    return arith.subi(a, b)


def mul(a, b):
    return arith.muli(a, b)


def band(a, b):
    return arith.andi(a, b)


def bor(a, b):
    return arith.ori(a, b)


def shl(a, b):
    return arith.shli(a, b)


def shr(a, b):
    return arith.shrui(a, b)


def lt(a, b):
    return arith.cmpi(arith.CmpIPredicate.slt, a, b)


def le(a, b):
    return arith.cmpi(arith.CmpIPredicate.sle, a, b)


def ge(a, b):
    return arith.cmpi(arith.CmpIPredicate.sge, a, b)



def eq(a, b):
    return arith.cmpi(arith.CmpIPredicate.eq, a, b)


def ne(a, b):
    return arith.cmpi(arith.CmpIPredicate.ne, a, b)


def sel(c, a, b):
    return arith.select(c, a, b)


def imin(a, b):
    return arith.minsi(a, b)


def imax(a, b):
    return arith.maxsi(a, b)


def udiv(a, b):
    return arith.divui(a, b)


def cdiv(a, b):
    return udiv(add(a, sub(b, ci(1))), b)


def ext64(a):
    return arith.extui(i64t(), a)


def p1():
    return ir.Type.parse("!llvm.ptr<1>")


def p3():
    return ir.Type.parse("!llvm.ptr<3>")


def gbase(t):
    return fx.Int64(fx.ptrtoint(fx.get_iter(t))).ir_value()


def lds_base(nbytes):
    alloc = fx.SharedAllocator(static=False)
    alloc.allocate(nbytes, 16)
    return llvm.ptrtoint(i32t(), fx.to_llvm_ptr(alloc.base_ptr))


def gload(addr64, ty, align):
    return llvm.load(ty, llvm.inttoptr(p1(), addr64), alignment=align)


def sload(addr64):
    """a uniform i32 the kernel does not write: a scalar load"""
    return llvm.load(i32t(), llvm.inttoptr(p1(), addr64), alignment=4, invariant=True)


def gstore(val, addr64, align):
    llvm.store(val, llvm.inttoptr(p1(), addr64), alignment=align)


def lload(addr32, ty, align):
    return llvm.load(ty, llvm.inttoptr(p3(), addr32), alignment=align)


def lstore(val, addr32, align):
    llvm.store(val, llvm.inttoptr(p3(), addr32), alignment=align)


def vext(v, i):
    return vector.extract(v, [], [i])


def exp2(x):
    if isinstance(x.type, ir.VectorType):
        n = ir.VectorType(x.type).shape[0]
        return vector.from_elements(x.type, [rocdl.exp2(f32t(), vext(x, i)) for i in range(n)])
    return rocdl.exp2(x.type, x)


def bcast4(x):
    return vector.broadcast(vt(4, f32t()), x)


def scf_for(lo, hi, inits, body):
    idx = ir.IndexType.get()
    op = scf.ForOp(arith.index_cast(idx, lo), arith.index_cast(idx, hi), arith.constant(idx, 1), inits)
    with ir.InsertionPoint(op.body):
        res = body(arith.index_cast(i32t(), op.induction_variable), list(op.inner_iter_args))
        scf.YieldOp(res)
    return list(op.results)


def scf_if(cond, then_fn, else_vals):
    """then_fn() -> values of else_vals' types"""
    op = scf.IfOp(cond, [v.type for v in else_vals], has_else=True)
    with ir.InsertionPoint(op.then_block):
        scf.YieldOp(list(then_fn()))
    with ir.InsertionPoint(op.else_block):
        scf.YieldOp(list(else_vals))
    return list(op.results)


def scf_if_else(cond, then_fn, else_fn, types_):
    op = scf.IfOp(cond, types_, has_else=True)
    with ir.InsertionPoint(op.then_block):
        scf.YieldOp(list(then_fn()))
    with ir.InsertionPoint(op.else_block):
        scf.YieldOp(list(else_fn()))
    return list(op.results)


def when(cond, fn):
    op = scf.IfOp(cond, [], has_else=False)
    with ir.InsertionPoint(op.then_block):
        fn()
        scf.YieldOp([])


def sgb(kind, n):
    fx.rocdl.sched_group_barrier(kind, n, 0)


def mfma(a, b, c):
    return fx.rocdl.mfma_f32_16x16x32_f16(vt(4, f32t()), [a, b, c])


def perm(hi, lo, s):
    return llvm.call_intrinsic(i32t(), "llvm.amdgcn.perm", [hi, lo, ci(s)], [], [])


def pk_mad_u16(a, b, c):
    # no op or intrinsic for v_pk_mad_u16; from plain IR LLVM emits a shift and an add instead
    return llvm.inline_asm(i32t(), [a, b, c], "v_pk_mad_u16 $0, $1, $2, $3", "=v,v,v,v", has_side_effects=False)


def pin(v):
    # no FlyDSL op: an opaque copy that keeps Q's loads issued in the prologue (the scheduler sinks them otherwise)
    return llvm.inline_asm(v.type, [v], "", "=v,0", has_side_effects=True)


def touch(*tensors):
    # no FlyDSL op: makes the argument pointers load at entry in one scalar round trip (else after the lengths)
    vals = [gbase(t) for t in tensors]
    llvm.inline_asm(None, vals, "", ",".join(["s"] * len(vals)), has_side_effects=True)


def lane_id():
    return rocdl.mbcnt_hi(i32t(), ci(-1), rocdl.mbcnt_lo(i32t(), ci(-1), ci(0)))


def shfl_xor(x, off):
    src = arith.xori(lane_id(), ci(off))
    r = rocdl.ds_bpermute(i32t(), shl(src, ci(2)), arith.bitcast(i32t(), x))
    return arith.bitcast(f32t(), r)


def _raw(x):
    return x.ir_value() if hasattr(x, "ir_value") else x


def _i32(x):
    v = _raw(x)
    if v.type == ir.IndexType.get():
        return arith.index_cast(i32t(), v)
    if v.type == i64t():
        return arith.trunci(i32t(), v)
    return v


# ---------------------------------------------------------------- the work split
def ucdiv(n, t):
    """ceil(n / t) for uniform 0 <= n, 1 <= t < 2^10: floor((n + t - 1/2) / t) in f32 is exact there"""
    x = arith.addf(arith.uitofp(f32t(), n), arith.subf(arith.uitofp(f32t(), t), cf(0.5)))
    return arith.fptoui(i32t(), arith.mulf(x, rocdl.rcp(f32t(), arith.uitofp(f32t(), t))))


class Work:
    """The split of the requests' tiles over GMAX workgroups (module docstring); uniform values, unrolled over
    the B requests. tpw: t0 = ceil(N / GMAX) or t0 + 1 if it fits, else tf = max(t0, ceil(nt_max / (GMAX // B))),
    which fits by construction (every request then takes at most GMAX // B workgroups)."""

    def __init__(self, swa_len, kv_len, B, GMAX, SWA_W, KV_W):
        self.B = B
        self.sl = [imax(imin(sload(add(gbase(swa_len), ci(4 * i, i64t()))), ci(SWA_W)), ci(0)) for i in range(B)]
        self.kl = [imax(imin(sload(add(gbase(kv_len), ci(4 * i, i64t()))), ci(KV_W)), ci(0)) for i in range(B)]
        self.nt = [shr(add(add(s, k), ci(TILE - 1)), ci(6)) for s, k in zip(self.sl, self.kl)]
        n_all = self.nt[0]
        for n in self.nt[1:]:
            n_all = add(n_all, n)
        nt_max = -(-(SWA_W + KV_W) // TILE)
        t0 = imax(cdiv(n_all, ci(GMAX)), ci(1))
        tpw = imax(t0, ci(-(-nt_max // (GMAX // B))))
        for t in (add(t0, ci(1)), t0):
            tot = None
            for n in self.nt:
                w = ucdiv(n, t)
                tot = w if tot is None else add(tot, w)
            tpw = sel(le(tot, ci(GMAX)), t, tpw)
        self.tpw = tpw
        self.W = [ucdiv(n, tpw) for n in self.nt]
        self.J, acc = [], ci(0)
        for w in self.W:
            self.J.append(acc)
            acc = add(acc, w)
        self.G = acc

    def pick(self, vals, b):
        r = vals[0]
        for i in range(1, self.B):
            r = sel(eq(b, ci(i)), vals[i], r)
        return r

    def of_wg(self, j):
        """(b, J_b, nt_b, sl_b, kl_b) of workgroup j < G: the last request with J_b <= j"""
        b = ci(0)
        for i in range(1, self.B):
            b = add(b, arith.extui(i32t(), le(self.J[i], j)))
        return [b] + [self.pick(v, b) for v in (self.J, self.nt, self.sl, self.kl)]


# ---------------------------------------------------------------- split kernel
def jw_offset(GMAX, H):
    """byte offset in ml of the (J_b, W_b) table, behind the slots' (m, l)"""
    return GMAX * H * 8


def ml_index(wv, c16):
    """(m, l) position of head 16 wv + c16 in its 64: heads h and h + 16 adjacent (the combine loads both at once)"""
    return add(add(shl(shr(wv, ci(1)), ci(5)), shl(c16, ci(1))), band(wv, ci(1)))


def _split_body(q, swa, swa_idx, swa_len, kv, kv_idx, kv_len, opart, ml, scale2,
                H, B, GMAX, SWA_PAGE, KV_PAGE, SWA_PB, KV_PB, SWA_W, KV_W):
    tid = _i32(fx.thread_idx.x)
    j = _i32(fx.block_idx.x)
    hg = _i32(fx.block_idx.y)
    touch(q, swa_idx, swa_len, kv_idx, kv_len)
    wk = Work(swa_len, kv_len, B, GMAX, SWA_W, KV_W)

    lbase = lds_base(LDS_SPLIT)
    ibase = add(lbase, ci(2 * BUF))
    pbase_l = add(ibase, ci(IDXB))
    abase_l = add(pbase_l, ci(8192))
    lbuf_l = add(abase_l, ci(256))

    wv = rocdl.readfirstlane(i32t(), shr(tid, ci(6)))
    lane = band(tid, ci(63))
    g = shr(lane, ci(4))
    c16 = band(lane, ci(15))
    r = shr(tid, ci(2))
    sb = band(tid, ci(3))

    active = lt(j, wk.G)
    breq, jb, nt_b, sl_b, kl_b = wk.of_wg(sel(active, j, ci(0)))
    x0 = mul(sub(j, jb), wk.tpw)
    x1 = sel(active, imin(add(x0, wk.tpw), nt_b), x0)
    T_b = add(sl_b, kl_b)

    def put_jw():
        for i in range(B):
            gstore(vector.from_elements(vt(2, i32t()), [wk.J[i], wk.W[i]]),
                   add(gbase(ml), ci(jw_offset(GMAX, H) + 8 * i, i64t())), 8)
    when(arith.andi(eq(add(j, hg), ci(0)), eq(tid, ci(0))), put_jw)

    sw_sh, kv_sh = SWA_PAGE.bit_length() - 1, KV_PAGE.bit_length() - 1
    sb_, kb = gbase(swa), gbase(kv)
    sib, kib = gbase(swa_idx), gbase(kv_idx)

    def buf_of(x):
        return add(lbase, mul(band(x, ci(1)), ci(BUF)))

    # ---------------- gather + dequantize: thread: row r = tid >> 2, 16-byte chunks (tid & 3) + 4i, i < 9
    def entry(x, rr):
        e = add(shl(x, ci(6)), rr)
        inr = arith.andi(lt(e, T_b), lt(x, x1))
        ec = sel(inr, e, ci(0))
        return inr, ec, lt(ec, sl_b)

    def idx_load(ent):
        """index of the workgroup's entry ent (tile x0 + ent / 64, row ent % 64)"""
        inr, ec, is_swa = entry(add(x0, shr(ent, ci(6))), band(ent, ci(63)))
        ia_s = add(sib, ext64(shl(add(mul(breq, ci(SWA_W)), ec), ci(2))))
        ia_k = add(kib, ext64(shl(add(mul(breq, ci(KV_W)), sel(is_swa, ci(0), sub(ec, sl_b))), ci(2))))
        return gload(sel(is_swa, ia_s, ia_k), i32t(), 4)

    def load_rows(x):
        idx = lload(add(ibase, shl(add(shl(sub(x, x0), ci(6)), r), ci(2))), i32t(), 4)
        inr, ec, is_swa = entry(x, r)
        valid = arith.andi(inr, ge(idx, ci(0)))
        slot = sel(valid, idx, ci(0))         # a missing key reads row 0 of page 0 (then masked)
        pg = sel(is_swa, shr(slot, ci(sw_sh)), shr(slot, ci(kv_sh)))
        rw = sel(is_swa, band(slot, ci(SWA_PAGE - 1)), band(slot, ci(KV_PAGE - 1)))
        pbase = add(sel(is_swa, sb_, kb), mul(ext64(pg), sel(is_swa, ci(SWA_PB, i64t()), ci(KV_PB, i64t()))))
        rowaddr = add(pbase, ext64(mul(rw, ci(576))))
        scaddr = add(pbase, ext64(add(sel(is_swa, ci(SWA_PAGE * 576), ci(KV_PAGE * 576)), shl(rw, ci(3)))))
        sc = gload(scaddr, vt(2, i32t()), 8)
        data = [gload(add(rowaddr, ext64(shl(add(sb, ci(4 * i)), ci(4)))), vt(4, i32t()), 16) for i in range(9)]
        return data + [sc, sel(valid, cf(0.0), cf(float("-inf")))]

    def zrows():
        return [vsplat(4, i32t(), 0)] * 9 + [vsplat(2, i32t(), 0), cf(float("-inf"))]

    def load_rows_c(x):
        return scf_if(lt(x, x1), lambda: load_rows(x), zrows())

    def dequant(x, st):
        """K row to f16. A code's value times 2^(c-127): with 120 <= c <= 134 for every lane of the wave the f16 bits
        s<<15 | (e + c - 119)<<10 | m<<7 directly (an integer multiply-add a 16-bit half); otherwise exponent field
        e + 8 times 2^(c-127) as an f16 multiply (exact for normal results; 2^(c-127) subnormal for c in [103, 113),
        zero below and for a missing key)"""
        data, sc, bias = st[:9], st[9], st[10]
        valid = arith.cmpf(arith.CmpFPredicate.OEQ, bias, cf(0.0))
        sc = sel(valid, sc, vsplat(2, i32t(), 0))
        buf = buf_of(x)
        rowl = add(buf, mul(r, ci(PITCH)))
        scw = [vext(sc, 0), vext(sc, 1)]
        sbytes = [band(shr(scw[i // 4], ci(8 * (i % 4))), ci(255)) for i in range(7)]
        mn, mx = sbytes[0], sbytes[0]
        for s in sbytes[1:]:
            mn, mx = arith.minui(mn, s), arith.maxui(mx, s)
        slow = arith.ori(lt(mn, ci(120)), lt(ci(134), mx))
        anyslow = ne(rocdl.ballot(i64t(), slow), ci(0, i64t()))
        c128 = ci(128 | (128 << 16))

        def convert(fast):
            for i in range(7):
                if fast:
                    f = shl(sub(sbytes[i], ci(119)), ci(10))
                else:
                    s = sbytes[i]
                    fb = sel(ge(s, ci(113)), shl(sub(s, ci(112)), ci(10)),
                             sel(ge(s, ci(103)), shl(ci(1), sub(s, ci(103))), ci(0)))
                    fv = llvm.bitcast(vt(2, f16t()), bor(fb, shl(fb, ci(16))))
                    f = ci(0x2000)
                addend = bor(f, shl(f, ci(16)))
                outs = []
                for k in range(4):
                    wd = vext(data[i], k)
                    mag = band(wd, ci(0x7F7F7F7F))
                    sg = band(shr(wd, ci(7)), ci(0x01010101))
                    for s_ in (0x05010400, 0x07030602):
                        y = pk_mad_u16(perm(sg, mag, s_), c128, addend)
                        if not fast:
                            y = llvm.bitcast(i32t(), arith.mulf(llvm.bitcast(vt(2, f16t()), y), fv))
                        outs.append(y)
                cofs = add(rowl, shl(add(sb, ci(4 * i)), ci(5)))
                lstore(vector.from_elements(vt(4, i32t()), outs[0:4]), cofs, 16)
                lstore(vector.from_elements(vt(4, i32t()), outs[4:8]), add(cofs, ci(16)), 16)
            return []
        scf_if_else(anyslow, lambda: convert(False), lambda: convert(True), [])
        for i in (7, 8):
            rb = llvm.bitcast(vt(8, bf16t()), sel(valid, data[i], vsplat(4, i32t(), 0)))
            rf = arith.truncf(vt(8, f16t()), arith.extf(vt(8, f32t()), rb))
            lstore(rf, add(rowl, add(ci(896 + 16 * (4 * i - 28)), shl(sb, ci(4)))), 16)
        lstore(bias, add(buf, add(ci(TILE * PITCH), shl(r, ci(2)))), 4)

    # ---------------- attention: QK wave wv = heads 16 wv .. 16 wv + 15 of the group
    head = add(add(shl(hg, ci(6)), shl(wv, ci(4))), c16)
    C = scale2
    slot_h = add(mul(j, ci(H // 64)), hg)

    def load_q():
        qaddr = add(gbase(q), ext64(add(shl(add(mul(breq, ci(H)), head), ci(10)), shl(g, ci(4)))))
        qs = [gload(add(qaddr, ci(64 * kk, i64t())), vt(8, bf16t()), 16) for kk in range(16)]
        return [arith.truncf(vt(8, f16t()), arith.extf(vt(8, f32t()), v)) for v in qs]

    def compute(x, qf, m_run, l_run, o, final=False):
        kbase = buf_of(x)
        arow = add(kbase, add(mul(c16, ci(PITCH)), shl(g, ci(4))))
        accs = []
        steps = [(m, kk) for m in range(4) for kk in range(16)]

        def rd(mk):
            return lload(add(arow, ci(16 * PITCH * mk[0] + 64 * mk[1])), vt(8, f16t()), 16)
        nxt = [rd(st) for st in steps[0:KB]]
        acc = None
        for i0 in range(0, 64, KB):
            cur = nxt
            if i0 + KB < 64:
                nxt = [rd(st) for st in steps[i0 + KB:i0 + 2 * KB]]
            for i in range(KB):
                m, kk = steps[i0 + i]
                if kk == 0:
                    acc = vsplat(4, f32t(), 0.0)
                acc = mfma(cur[i], qf[kk], acc)
                if kk == 15:
                    accs.append(acc)
        # the first batch's reads, then each MFMA followed by one read of the next batch
        sgb("ds_read", KB)
        for i0 in range(0, 64, KB):
            for _ in range(KB):
                sgb("mfma_wmma", 1)
                if i0 + KB < 64:
                    sgb("ds_read", 1)
        bias_b = add(kbase, ci(TILE * PITCH))
        s = []
        for m in range(4):
            bv = lload(add(bias_b, shl(add(ci(16 * m), shl(g, ci(2))), ci(2))), vt(4, f32t()), 16)
            s.append(arith.addf(arith.mulf(accs[m], bcast4(C)), bv))
        tmax = None
        for m in range(4):
            for jj in range(4):
                xv = vext(s[m], jj)
                tmax = xv if tmax is None else arith.maximumf(tmax, xv)
        tmax = arith.maximumf(tmax, shfl_xor(tmax, 16))
        tmax = arith.maximumf(tmax, shfl_xor(tmax, 32))
        need = arith.cmpf(arith.CmpFPredicate.OGT, tmax, arith.addf(m_run, cf(8.0)))
        m_new = sel(need, tmax, m_run)
        alpha = sel(need, exp2(arith.subf(m_run, m_new)), cf(1.0))
        p = [exp2(arith.subf(s[m], bcast4(m_new))) for m in range(4)]
        psum = None
        for m in range(4):
            for jj in range(4):
                xv = vext(p[m], jj)
                psum = xv if psum is None else arith.addf(psum, xv)
        l_new = arith.addf(arith.mulf(l_run, alpha), psum)
        pb = [arith.truncf(vt(8, f16t()), vector.shuffle(p[2 * ks], p[2 * ks + 1], list(range(8)))) for ks in range(2)]
        # P^T and alpha to LDS: PV's B operand (ht, ks) is wave ht's pb[ks], lane for lane
        for ks in range(2):
            lstore(pb[ks], add(pbase_l, add(shl(wv, ci(11)), add(ci(1024 * ks), shl(lane, ci(4))))), 16)
        when(eq(g, ci(0)), lambda: lstore(alpha, add(abase_l, shl(add(shl(wv, ci(4)), c16), ci(2))), 4))
        if final:
            lt_ = arith.addf(l_new, shfl_xor(l_new, 16))
            lt_ = arith.addf(lt_, shfl_xor(lt_, 32))
            prow = add(shl(slot_h, ci(6)), ml_index(wv, c16))
            gstore(vector.from_elements(vt(2, f32t()), [m_new, lt_]), add(gbase(ml), ext64(shl(prow, ci(3)))), 8)
            when(eq(g, ci(0)), lambda: lstore(lt_, add(lbuf_l, shl(add(shl(wv, ci(4)), c16), ci(2))), 4))
        fx.gpu.barrier()
        pbs = [[lload(add(pbase_l, add(ci(2048 * ht + 1024 * ks), shl(lane, ci(4)))), vt(8, f16t()), 16)
                for ks in range(2)] for ht in range(4)]
        als = [lload(add(abase_l, shl(add(ci(16 * ht), c16), ci(2))), f32t(), 4) for ht in range(4)]
        anyr = arith.cmpf(arith.CmpFPredicate.UNE, arith.minimumf(arith.minimumf(als[0], als[1]),
                                                                    arith.minimumf(als[2], als[3])), cf(1.0))
        anyw = ne(rocdl.ballot(i64t(), anyr), ci(0, i64t()))
        o = scf_if(anyw, lambda: [arith.mulf(o[i], bcast4(als[i % 4])) for i in range(32)], o)
        trb = add(kbase, add(add(mul(add(shl(g, ci(2)), shr(c16, ci(2))), ci(PITCH)), shl(band(c16, ci(3)), ci(3))),
                             shl(wv, ci(8))))

        def tr_reads(dt):
            res = []
            for ks in range(2):
                parts = [rocdl.ds_read_tr16_b64(vt(4, f16t()), llvm.inttoptr(
                    p3(), add(trb, ci(16 * mm * PITCH + 32 * dt)))) for mm in (2 * ks, 2 * ks + 1)]
                res.append(vector.shuffle(parts[0], parts[1], list(range(8))))
            return res

        out = []
        if final:
            inv = []
            for ht in range(4):
                lv = lload(add(lbuf_l, shl(add(ci(16 * ht), c16), ci(2))), f32t(), 4)
                inv.append(sel(arith.cmpf(arith.CmpFPredicate.OGT, lv, cf(0.0)), arith.divf(cf(1.0), lv), cf(0.0)))
            obase = add(gbase(opart), ext64(add(shl(slot_h, ci(16)), add(shl(wv, ci(14)), shl(lane, ci(4))))))

        def store_dt(dt):
            for hp in range(2):
                v = vector.shuffle(arith.mulf(out[dt * 4 + 2 * hp], bcast4(inv[2 * hp])),
                                   arith.mulf(out[dt * 4 + 2 * hp + 1], bcast4(inv[2 * hp + 1])), list(range(8)))
                gstore(arith.truncf(vt(8, f16t()), v), add(obase, ci((dt * 2 + hp) * 1024, i64t())), 16)
        nxt = [tr_reads(dt) for dt in range(DTB)]
        for dt0 in range(0, 8, DTB):
            cur = nxt
            if dt0 + DTB < 8:
                nxt = [tr_reads(dt) for dt in range(dt0 + DTB, dt0 + 2 * DTB)]
            for i in range(DTB):
                for ht in range(4):
                    acc = o[(dt0 + i) * 4 + ht]
                    for ks in range(2):
                        acc = mfma(cur[i][ks], pbs[ht][ks], acc)
                    out.append(acc)
                if final:
                    store_dt(dt0 + i)
        sgb("ds_read", 4 * DTB)
        for dt0 in range(0, 8, DTB):
            for k in range(8 * DTB):
                sgb("mfma_wmma", 1)
                if dt0 + DTB < 8 and k % 2 == 0:
                    sgb("ds_read", 1)
        return m_new, l_new, out

    def go():
        # prologue: the indices to LDS; tile x0 dequantized, x0 + 1 and x0 + 2 in registers
        nchunk = shr(add(sub(x1, x0), ci(7)), ci(3))           # 8 tiles (512 entries) a chunk
        iv = [idx_load(add(ci(256 * k), tid)) for k in range(2)]
        qf0 = load_q()
        fx.rocdl.s_waitcnt(vmcnt=16)
        for k in range(2):
            lstore(iv[k], add(ibase, shl(add(ci(256 * k), tid), ci(2))), 4)

        def more(ck, _):
            for k in range(2):
                ent = add(shl(ck, ci(9)), add(ci(256 * k), tid))
                lstore(idx_load(ent), add(ibase, shl(ent, ci(2))), 4)
            return []
        scf_for(ci(1), nchunk, [], more)
        fx.gpu.barrier()
        st0 = load_rows(x0)
        S0 = load_rows_c(add(x0, ci(1)))
        S1 = load_rows_c(add(x0, ci(2)))
        qf0 = [pin(v) for v in qf0]
        dequant(x0, st0)
        fx.gpu.barrier()
        o0 = [vsplat(4, f32t(), 0.0) for _ in range(32)]
        NA = 50                                        # m, l, o[32], qf[16]

        def step(x, att, S):
            """one tile (not the last): dequantize x + 1, load x + 3, attend x"""
            m_run, l_run, o, qf = att[0], att[1], att[2:34], att[34:50]
            dequant(add(x, ci(1)), S)
            S_n = load_rows_c(add(x, ci(3)))
            m_new, l_new, o = compute(x, qf, m_run, l_run, o)
            fx.gpu.barrier()
            return [m_new, l_new] + o + qf, S_n

        def pair(kp, args):
            att, S0_, S1_ = args[0:NA], args[NA:NA + 11], args[NA + 11:NA + 22]
            x = add(x0, shl(kp, ci(1)))
            att, S0_ = step(x, att, S0_)
            att, S1_ = step(add(x, ci(1)), att, S1_)
            return att + S0_ + S1_

        n = sub(x1, x0)
        res = scf_for(ci(0), shr(sub(n, ci(1)), ci(1)), [cf(NEG_BIG), cf(0.0)] + o0 + qf0 + S0 + S1, pair)
        att, S0_ = res[0:NA], res[NA:NA + 11]
        att = scf_if(eq(band(n, ci(1)), ci(0)), lambda: step(sub(x1, ci(2)), att, S0_)[0], att)
        compute(sub(x1, ci(1)), att[34:50], att[0], att[1], att[2:34], final=True)

    when(lt(x0, x1), go)


# ---------------------------------------------------------------- combine kernel
def _combine_body(opart, ml, sink, out, lse, kvs, H, B, GMAX, CT, NG, UNR):
    """block (b, hg, ph): LN = CT / NG lanes cover a slice of the 1 KB part ph / PS of O ([w][dt][head pair] native
    layout); thread (lane, group sg) merges slots sg, sg + NG, ... for its 8 values; group 0 merges the groups"""
    tid = _i32(fx.thread_idx.x)
    bhg = _i32(fx.block_idx.x)
    ph = _i32(fx.block_idx.y)
    LN = CT // NG
    PS = 64 // LN
    HG = H // 64
    part = udiv(ph, ci(PS))
    b = udiv(bhg, ci(HG))
    hg = sub(bhg, mul(b, ci(HG)))
    sg = udiv(tid, ci(LN))
    li = add(mul(sub(ph, mul(part, ci(PS))), ci(LN)), band(tid, ci(LN - 1)))
    c16 = band(li, ci(15))
    g = shr(li, ci(4))
    hp = band(part, ci(1))
    dt = band(shr(part, ci(1)), ci(7))
    w = shr(part, ci(4))
    hA = add(shl(hp, ci(5)), c16)                      # heads 16(2hp) + c16 and 16(2hp+1) + c16
    hB = add(hA, ci(16))
    lb = lds_base(CT * 48)
    mlb, ob = gbase(ml), gbase(opart)
    jw = llvm.load(vt(2, i32t()), llvm.inttoptr(p1(), add(mlb, add(ci(jw_offset(GMAX, H), i64t()), ext64(shl(b, ci(3)))))),
                   alignment=8, invariant=True)        # written by the split kernel: read-only here (a scalar load)
    jlo, n = vext(jw, 0), vext(jw, 1)
    z4 = vsplat(4, f32t(), 0.0)
    skA = gload(add(gbase(sink), ext64(shl(add(shl(hg, ci(6)), hA), ci(2)))), f32t(), 4)
    skB = gload(add(gbase(sink), ext64(shl(add(shl(hg, ci(6)), hB), ci(2)))), f32t(), 4)

    def body(it, args):
        MA, LA, aA, MB, LB, aB = args
        ld = []
        for u in range(UNR):
            i = add(mul(it, ci(NG * UNR)), add(sg, ci(NG * u)))
            ok = lt(i, n)
            sh = add(mul(add(jlo, sel(ok, i, ci(0))), ci(HG)), hg)
            m4 = gload(add(mlb, ext64(shl(add(shl(sh, ci(6)), add(shl(hp, ci(5)), shl(c16, ci(1)))), ci(3)))),
                       vt(4, f32t()), 16)
            ov = gload(add(ob, ext64(add(shl(sh, ci(16)), add(shl(part, ci(10)), shl(li, ci(4)))))), vt(8, f16t()), 16)
            ld.append((ok, vector.shuffle(m4, m4, [0, 1]), vector.shuffle(m4, m4, [2, 3]), ov))
        res = []
        for hi, (M, L, acc) in enumerate(((MA, LA, aA), (MB, LB, aB))):
            Mn = M
            for ok, mA, mB, ov in ld:
                mv = mA if hi == 0 else mB
                Mn = arith.maximumf(Mn, sel(ok, vext(mv, 0), cf(NEG_BIG)))
            a = exp2(arith.subf(M, Mn))
            L = arith.mulf(L, a)
            acc = arith.mulf(acc, bcast4(a))
            for ok, mA, mB, ov in ld:
                mv = mA if hi == 0 else mB
                lj = vext(mv, 1)
                use = arith.andi(ok, arith.cmpf(arith.CmpFPredicate.OGT, lj, cf(0.0)))
                wj = arith.mulf(exp2(arith.subf(vext(mv, 0), Mn)), lj)
                o4 = arith.extf(vt(4, f32t()), vector.shuffle(ov, ov, [4 * hi + k for k in range(4)]))
                L = arith.addf(L, sel(use, wj, cf(0.0)))
                acc = arith.addf(acc, sel(use, arith.mulf(o4, bcast4(wj)), z4))
            res += [Mn, L, acc]
        return res

    MA, LA, aA, MB, LB, aB = scf_for(ci(0), cdiv(n, ci(NG * UNR)), [cf(NEG_BIG), cf(0.0), z4] * 2, body)
    base = add(lb, mul(tid, ci(48)))
    lstore(vector.from_elements(vt(4, f32t()), [MA, LA, MB, LB]), base, 16)
    lstore(aA, add(base, ci(16)), 16)
    lstore(aB, add(base, ci(32)), 16)
    fx.gpu.barrier()

    def fin():
        for hi, hh in enumerate((hA, hB)):
            M = cf(NEG_BIG)
            parts = []
            for k in range(NG):
                bb = add(lb, mul(add(ci(LN * k), band(tid, ci(LN - 1))), ci(48)))
                mlv = lload(bb, vt(4, f32t()), 16)
                parts.append((vext(mlv, 2 * hi), vext(mlv, 2 * hi + 1),
                              lload(add(bb, ci(16 + 16 * hi)), vt(4, f32t()), 16)))
                M = arith.maximumf(M, parts[-1][0])
            L = cf(0.0)
            tot = z4
            for mk, lk, ak in parts:
                wk_ = exp2(arith.subf(mk, M))
                L = arith.addf(L, arith.mulf(wk_, lk))
                tot = arith.addf(tot, arith.mulf(ak, bcast4(wk_)))
            sk = skA if hi == 0 else skB
            den = arith.addf(L, exp2(arith.subf(arith.mulf(sk, cf(LOG2E)), M)))
            empty = arith.cmpf(arith.CmpFPredicate.OLE, L, cf(0.0))
            fac = sel(empty, cf(0.0), arith.divf(kvs, den))
            row = add(mul(b, ci(H)), add(shl(hg, ci(6)), hh))
            dim = add(add(shl(w, ci(7)), shl(dt, ci(4))), shl(g, ci(2)))
            gstore(arith.truncf(vt(4, bf16t()), arith.mulf(tot, bcast4(fac))),
                   add(gbase(out), ext64(add(shl(row, ci(10)), shl(dim, ci(1))))), 8)
            lv = sel(empty, cf(float("inf")), arith.mulf(arith.addf(M, rocdl.log(f32t(), L)), cf(math.log(2.0))))
            when(arith.andi(eq(add(w, dt), ci(0)), eq(g, ci(0))),
                 lambda lv=lv, row=row: gstore(lv, add(gbase(lse), ext64(shl(row, ci(2)))), 4))
    when(eq(sg, ci(0)), fin)


@flyc.kernel
def split_kernel(q: fx.Tensor, swa: fx.Tensor, swa_idx: fx.Tensor, swa_len: fx.Tensor, kv: fx.Tensor,
                 kv_idx: fx.Tensor, kv_len: fx.Tensor, opart: fx.Tensor, ml: fx.Tensor, scale2: fx.Float32,
                 H: fx.Constexpr[int], B: fx.Constexpr[int], GMAX: fx.Constexpr[int], SWA_PAGE: fx.Constexpr[int],
                 KV_PAGE: fx.Constexpr[int], SWA_PB: fx.Constexpr[int], KV_PB: fx.Constexpr[int],
                 SWA_W: fx.Constexpr[int], KV_W: fx.Constexpr[int]):
    _split_body(q, swa, swa_idx, swa_len, kv, kv_idx, kv_len, opart, ml, _raw(scale2),
                H, B, GMAX, SWA_PAGE, KV_PAGE, SWA_PB, KV_PB, SWA_W, KV_W)


@flyc.kernel
def combine_kernel(opart: fx.Tensor, ml: fx.Tensor, sink: fx.Tensor, out: fx.Tensor, lse: fx.Tensor,
                   kvs: fx.Float32, H: fx.Constexpr[int], B: fx.Constexpr[int], GMAX: fx.Constexpr[int],
                   CT: fx.Constexpr[int], NG: fx.Constexpr[int], UNR: fx.Constexpr[int]):
    touch(opart, ml, sink, out, lse)
    _combine_body(opart, ml, sink, out, lse, _raw(kvs), H, B, GMAX, CT, NG, UNR)


@flyc.jit
def _launch(q: fx.Tensor, swa: fx.Tensor, swa_idx: fx.Tensor, swa_len: fx.Tensor, kv: fx.Tensor, kv_idx: fx.Tensor,
            kv_len: fx.Tensor, sink: fx.Tensor, out: fx.Tensor, lse: fx.Tensor, opart: fx.Tensor, ml: fx.Tensor,
            scale2: fx.Float32, kvs: fx.Float32, H: fx.Constexpr[int], B: fx.Constexpr[int],
            GMAX: fx.Constexpr[int], SWA_PAGE: fx.Constexpr[int], KV_PAGE: fx.Constexpr[int],
            SWA_PB: fx.Constexpr[int], KV_PB: fx.Constexpr[int], SWA_W: fx.Constexpr[int], KV_W: fx.Constexpr[int],
            CT: fx.Constexpr[int], NG: fx.Constexpr[int], UNR: fx.Constexpr[int],
            stream: fx.Stream = fx.Stream(None)):
    split_kernel(q, swa, swa_idx, swa_len, kv, kv_idx, kv_len, opart, ml, scale2, H, B, GMAX, SWA_PAGE, KV_PAGE,
                 SWA_PB, KV_PB, SWA_W, KV_W).launch(grid=(GMAX, H // 64, 1), block=(256, 1, 1), stream=stream)
    combine_kernel(opart, ml, sink, out, lse, kvs, H, B, GMAX, CT, NG, UNR).launch(
        grid=(B * (H // 64), 64 * 64 * NG // CT, 1), block=(CT, 1, 1), stream=stream)


@functools.cache
def _plan(B, H, swa_page, kv_page, swa_pb, kv_pb, swa_w, kv_w, sm_scale, kv_scale):
    """compiles for a shape and its scalars: (launch(q, swa, ... ml, stream=...), O-partial and (m, l) scratch sizes)"""
    assert H % 64 == 0 and B >= 1
    assert swa_page & (swa_page - 1) == 0 and kv_page & (kv_page - 1) == 0
    GMAX = 256 // (H // 64)
    assert B <= GMAX, "a request needs a workgroup of its own"
    nt_max = -(-(swa_w + kv_w) // TILE)
    # the largest tpw the work split can choose (class Work) must fit the LDS index staging
    assert max(-(-B * nt_max // GMAX), -(-nt_max // (GMAX // B))) <= MAXT, "more than MAXT tiles a workgroup"
    CT, NG, UNR = _COMBINE.get((B, H), (256, max(4, 16 // (B * H // 64)), 8))
    launch = functools.partial(
        flyc.compile[{"waves_per_eu": 1}](_launch), scale2=float(sm_scale * kv_scale * LOG2E), kvs=float(kv_scale),
        H=H, B=B, GMAX=GMAX, SWA_PAGE=swa_page, KV_PAGE=kv_page, SWA_PB=swa_pb, KV_PB=kv_pb, SWA_W=swa_w, KV_W=kv_w,
        CT=CT, NG=NG, UNR=UNR)
    return launch, GMAX * H * D, GMAX * H * 2 + 2 * B


def _flat_pool(pool):
    """[pages][page_rows][1][584] fp8 view over padded pages -> 1-D bytes from the first page, and its page bytes"""
    u8 = pool.view(torch.uint8)
    return torch.as_strided(u8, (u8.shape[0] * u8.stride(0),), (1,)), u8.stride(0)


def run(*, q, kv_cache, sparse_indices, sparse_lens, extra_kv_cache, extra_sparse_indices, extra_sparse_lens,
        block_table=None, cache_seqlens=None, cu_seqlens_k=None, causal=False, head_dim_v=D, sm_scale, sinks,
        kv_cache_format="dsv4_fp8", kv_scale=1.0, return_lse=True, kv_cache_layout="padded_pages", output, lse=None):
    """The AKLR entry: q [B][1][H][512] bf16; pools fp8 [pages][page_rows][1][584] (padded pages);
    indices [B][1][width] int32; lens [B] int32; sinks [H] f32; writes output [B][1][H][512] bf16 and lse [B][1][H]"""
    assert kv_cache_format == "dsv4_fp8" and kv_cache_layout == "padded_pages" and head_dim_v == D and not causal
    assert block_table is None and cache_seqlens is None and cu_seqlens_k is None
    assert q.dtype == torch.bfloat16 and q.is_contiguous() and output.is_contiguous()
    assert sparse_indices.dtype == extra_sparse_indices.dtype == sparse_lens.dtype == extra_sparse_lens.dtype \
        == torch.int32 and sinks.dtype == torch.float32
    B, _, H, _ = q.shape
    swa, swa_pb = _flat_pool(kv_cache)
    kv, kv_pb = _flat_pool(extra_kv_cache)
    launch, n_o, n_ml = _plan(B, H, kv_cache.shape[1], extra_kv_cache.shape[1], swa_pb, kv_pb,
                              sparse_indices.shape[-1], extra_sparse_indices.shape[-1], float(sm_scale), float(kv_scale))
    opart = torch.empty(n_o, dtype=torch.float16, device=q.device)
    ml = torch.empty(n_ml, dtype=torch.float32, device=q.device)
    if lse is None:
        lse = torch.empty((B, 1, H), dtype=torch.float32, device=q.device)
    launch(q, swa, sparse_indices, sparse_lens, kv, extra_sparse_indices, extra_sparse_lens, sinks, output, lse,
           opart, ml, stream=fx.Stream(torch.cuda.current_stream()))
    return (output, lse) if return_lse else output
